// Generated by `npx auth generate` (better-auth's own tables); hand-written tables follow. SPEC-habits §2.
import { relations, sql } from 'drizzle-orm'
import { check, date, index, integer, pgEnum, pgTable, primaryKey, text, timestamp, uuid } from 'drizzle-orm/pg-core'
import { user } from './auth-schema.ts'

export * from './auth-schema.ts'

export const timeSettings = pgTable(
  'time_settings',
  {
    userId: text('user_id').primaryKey().references(() => user.id, { onDelete: 'cascade' }),
    timeZone: text('time_zone').notNull(),
    dayStartMinutes: integer('day_start_minutes').notNull().default(0),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [check('day_start_minutes_range', sql`${t.dayStartMinutes} between 0 and 360`)],
)

export const habit = pgTable(
  'habit',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    userId: text('user_id').notNull().references(() => user.id, { onDelete: 'cascade' }),
    name: text('name').notNull(),
    stackCue: text('stack_cue'),
    createdOn: date('created_on').notNull(), // the user's local date at creation
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index('habit_user_id_idx').on(t.userId),
    check('habit_name_length', sql`char_length(${t.name}) between 1 and 80`),
    check('habit_stack_cue_length', sql`char_length(${t.stackCue}) <= 120`),
  ],
)

export const frequencyKind = pgEnum('frequency_kind', ['daily', 'weekly', 'interval'])

// One row per frequency change; past periods keep the rule that was in effect (SPEC-habits §6).
export const habitSchedule = pgTable(
  'habit_schedule',
  {
    habitId: uuid('habit_id').notNull().references(() => habit.id, { onDelete: 'cascade' }),
    effectiveFrom: date('effective_from').notNull(),
    kind: frequencyKind('kind').notNull(),
    weeklyTarget: integer('weekly_target'),
    intervalDays: integer('interval_days'),
  },
  (t) => [
    primaryKey({ columns: [t.habitId, t.effectiveFrom] }),
    check('habit_schedule_weekly_target', sql`${t.weeklyTarget} between 1 and 7`),
    check('habit_schedule_interval_days', sql`${t.intervalDays} between 2 and 30`),
    check('habit_schedule_weekly_has_target', sql`(${t.kind} = 'weekly') = (${t.weeklyTarget} is not null)`),
    check('habit_schedule_interval_has_days', sql`(${t.kind} = 'interval') = (${t.intervalDays} is not null)`),
  ],
)

export const checkIn = pgTable(
  'check_in',
  {
    habitId: uuid('habit_id').notNull().references(() => habit.id, { onDelete: 'cascade' }),
    onDate: date('on_date').notNull(), // a local habit day, not an instant
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [primaryKey({ columns: [t.habitId, t.onDate] })],
)

// For relational queries only; relations add no columns or constraints.
export const habitRelations = relations(habit, ({ many }) => ({ schedules: many(habitSchedule), checkIns: many(checkIn) }))
export const habitScheduleRelations = relations(habitSchedule, ({ one }) => ({
  habit: one(habit, { fields: [habitSchedule.habitId], references: [habit.id] }),
}))
export const checkInRelations = relations(checkIn, ({ one }) => ({
  habit: one(habit, { fields: [checkIn.habitId], references: [habit.id] }),
}))
